def find_sequence_with_subsequences(n):
    target = "1337"
    max_length = 10**5
    dp = [0] * (len(target) + 1)
    dp[0] = 1

    # Precompute multipliers for each digit
    multipliers = [1]
    for _ in range(len(target)):
        multipliers.append(multipliers[-1] * 3)

    # Binary search for the smallest length
    left, right = 1, max_length
    while left < right:
        mid = (left + right) // 2
        dp = [0] * (len(target) + 1)
        dp[0] = 1

        for i in range(mid):
            for j in range(len(target) - 1, -1, -1):
                dp[j + 1] += dp[j] * 3

        if dp[len(target)] >= n:
            right = mid
        else:
            left = mid + 1

    # Construct the sequence
    sequence = []
    remaining = n
    for i in range(left - 1, -1, -1):
        digit_index = len(sequence)
        for digit in "137":
            if remaining <= 0:
                break
            count = dp[len(target)] * multipliers[len(sequence)] // 3
            if remaining <= count:
                sequence.append(digit)
                remaining -= 1
                break
            remaining -= count
            dp[len(target)] -= count
            dp[len(target) - 1] += count

    return ''.join(sequence)

