import sys

def find_sequence(n):
    if n == 1:
        return "1337"

    dp = [0] * (n + 1)
    dp[1] = 1

    sequence = []
    current = 1

    while dp[current] < n:
        if current * 2 <= n:
            dp[current * 2] = dp[current] * 2
        if current * 3 <= n:
            dp[current * 3] = dp[current] * 2

        if dp[current] < n:
            sequence.append('1' if len(sequence) % 3 == 0 else '3' if len(sequence) % 3 == 1 else '7')

        current += 1

    return ''.join(sequence)

