def find_sequence(n):
    base = [1, 3, 3, 3, 7]
    result = []
    count = 0
    i = 0

    while count < n:
        if i >= len(result):
            result.append(base[i % 5])
        elif result[i] == 1 and i >= 3 and result[i-1:i+1] == [3, 3]:
            result.insert(i+1, 3)
        elif result[i] == 3 and i >= 2 and result[i-1:i+1] == [3, 7]:
            result.insert(i+1, 3)
        i += 1

